    if columns is None:
        columns = arr_columns = ensure_index(sorted(data))
        arrays = [data[k] for k in columns]
    else:
        arrays = []
        arr_columns_list = []
        for k, v in data.items():
            if k in columns:
                arr_columns_list.append(k)
                arrays.append(v)

        arr_columns = Index(arr_columns_list)
        arrays, arr_columns, result_index = maybe_reorder(
